-- Exam-focused copy refresh for daily_motivational_phrases (see scripts/emit-daily-motivational-seed.mjs).
UPDATE public.daily_motivational_phrases SET phrase = $dm001$Rank is not luck—it is compound interest on revision hours the hall never sees coming.$dm001$ WHERE phrase = $dm001$Rank is not luck—it is compound interest on hours no one claps for.$dm001$;
UPDATE public.daily_motivational_phrases SET phrase = $dm002$You are not behind; you are unfinished. Finish today’s syllabus slice the way the paper will ask it.$dm002$ WHERE phrase = $dm002$You are not behind; you are unfinished. Finish today’s slice.$dm002$;
UPDATE public.daily_motivational_phrases SET phrase = $dm003$Motivation lands after the first question—not before. Open a page of attempts, begin now.$dm003$ WHERE phrase = $dm003$Motivation arrives after you start—not before. Begin ugly, begin now.$dm003$;
UPDATE public.daily_motivational_phrases SET phrase = $dm004$The final paper will not care how inspired you felt—only what you practiced until it felt automatic.$dm004$ WHERE phrase = $dm004$The chair does not care about your inspiration—only your hours.$dm004$;
UPDATE public.daily_motivational_phrases SET phrase = $dm005$The scoring paper rewards the cadence that survives tired weekdays, not spikes that quit every third week.$dm005$ WHERE phrase = $dm005$Consistency beats intensity that quits every third day.$dm005$;
UPDATE public.daily_motivational_phrases SET phrase = $dm006$Result morning reads your mocks and error logs, not your study intentions.$dm006$ WHERE phrase = $dm006$Your future self is watching receipts, not intentions.$dm006$;
UPDATE public.daily_motivational_phrases SET phrase = $dm007$A calm exam hour is boring repetition dressed up as one pass through the hall.$dm007$ WHERE phrase = $dm007$Winning is boring repetition dressed up as one dramatic day.$dm007$;
UPDATE public.daily_motivational_phrases SET phrase = $dm008$If you can still solve basics when it is hard, the tough questions feel lighter on test day.$dm008$ WHERE phrase = $dm008$If you can do the easy when it is hard, the hard becomes easier.$dm008$;
UPDATE public.daily_motivational_phrases SET phrase = $dm009$Discipline is loving your target enough to run another timed set on purpose.$dm009$ WHERE phrase = $dm009$Discipline is loving your goal enough to bore yourself on purpose.$dm009$;
UPDATE public.daily_motivational_phrases SET phrase = $dm010$Consistency is king—and the throne is built from tiny daily revisions and mock reviews.$dm010$ WHERE phrase = $dm010$Consistency is king—and the throne is built from tiny daily bricks.$dm010$;
UPDATE public.daily_motivational_phrases SET phrase = $dm011$If today feels pointless, one timed section still moves your exam readiness forward.$dm011$ WHERE phrase = $dm011$If today feels pointless, remember invisible roots still grow.$dm011$;
UPDATE public.daily_motivational_phrases SET phrase = $dm012$You are not here to scroll in comfort; you are here to become capable under a ticking clock.$dm012$ WHERE phrase = $dm012$You are not here to be comfortable; you are here to become capable.$dm012$;
UPDATE public.daily_motivational_phrases SET phrase = $dm013$The best test-week strategy is the study block you can repeat tomorrow with a timer on.$dm013$ WHERE phrase = $dm013$The best strategy is the one you can repeat tomorrow.$dm013$;
UPDATE public.daily_motivational_phrases SET phrase = $dm014$You do not need perfect silence to begin; you need one honest attempt block today.$dm014$ WHERE phrase = $dm014$You do not need permission to begin; you need a chair.$dm014$;
UPDATE public.daily_motivational_phrases SET phrase = $dm015$Never trade your long exam prep arc for one panicked hour before a mock.$dm015$ WHERE phrase = $dm015$Never give up the long game for a bad hour.$dm015$;
UPDATE public.daily_motivational_phrases SET phrase = $dm016$Mocks are dress rehearsals—miss badly on paper, fix the leak, sit another section.$dm016$ WHERE phrase = $dm016$Mocks are rehearsals—bow badly, adjust the script, bow again.$dm016$;
UPDATE public.daily_motivational_phrases SET phrase = $dm017$Exam discipline is keeping notebook promises while the invigilator is still months away.$dm017$ WHERE phrase = $dm017$Discipline is keeping promises to yourself at whisper volume.$dm017$;
UPDATE public.daily_motivational_phrases SET phrase = $dm018$Never giving up is not never resting—it is never abandoning the syllabus map you drew.$dm018$ WHERE phrase = $dm018$Never giving up is not never resting—it is never abandoning the path.$dm018$;
UPDATE public.daily_motivational_phrases SET phrase = $dm019$If you can still protect today’s minimum attempts on your worst day, the real paper will find you trained.$dm019$ WHERE phrase = $dm019$If you can do today’s minimum on your worst day, you will survive the season.$dm019$;
UPDATE public.daily_motivational_phrases SET phrase = $dm020$Stop chasing perfect prep weather; chase a repeatable pre-paper start ritual.$dm020$ WHERE phrase = $dm020$Stop chasing perfect conditions; chase a repeatable start ritual.$dm020$;
UPDATE public.daily_motivational_phrases SET phrase = $dm021$The calmer hall version of you needs today’s you to finish one uncomfortable timed block.$dm021$ WHERE phrase = $dm021$Your future self needs today’s you to be slightly braver than comfortable.$dm021$;
UPDATE public.daily_motivational_phrases SET phrase = $dm022$If inspiration left, let your next revision slot carry you into fresh questions—use it kindly.$dm022$ WHERE phrase = $dm022$If inspiration left, obligation can carry you—use it kindly.$dm022$;
UPDATE public.daily_motivational_phrases SET phrase = $dm023$Honest mocks today are small installments toward calm on result day—pay all term, not in one cram week.$dm023$ WHERE phrase = $dm023$Pain today is the price list of pride on result day—pay in installments, not lump sum.$dm023$;
UPDATE public.daily_motivational_phrases SET phrase = $dm024$One honest hour of timed questions beats three distracted ones with a highlighter and a dream.$dm024$ WHERE phrase = $dm024$One honest hour beats three distracted ones with a highlighter and a dream.$dm024$;
UPDATE public.daily_motivational_phrases SET phrase = $dm025$When motivation fades, your exam warm-up ritual remains—protect that routine.$dm025$ WHERE phrase = $dm025$When motivation fades, ritual remains. Protect the ritual.$dm025$;
UPDATE public.daily_motivational_phrases SET phrase = $dm026$Cut the hallway drama in your head; put the timer on the next set.$dm026$ WHERE phrase = $dm026$Cut the drama; add the timer.$dm026$;
UPDATE public.daily_motivational_phrases SET phrase = $dm027$Replace “I should revise” with “I did 25 timed questions”—small receipts matter before the paper.$dm027$ WHERE phrase = $dm027$Replace ‘I should’ with ‘I did 25 minutes’—small receipts matter.$dm027$;
UPDATE public.daily_motivational_phrases SET phrase = $dm028$You grow score potential fastest where you feel slowest—stay in that chapter with questions.$dm028$ WHERE phrase = $dm028$You grow fastest where you feel slowest—stay in that topic.$dm028$;
UPDATE public.daily_motivational_phrases SET phrase = $dm029$If exam doubt is loud, let one scored practice set be louder for twenty minutes.$dm029$ WHERE phrase = $dm029$If doubt is loud, let action be louder for twenty minutes.$dm029$;
UPDATE public.daily_motivational_phrases SET phrase = $dm030$When fear says skip the section, open five minutes of warm-up questions instead.$dm030$ WHERE phrase = $dm030$When fear says skip, answer with a five-minute warm-up.$dm030$;
UPDATE public.daily_motivational_phrases SET phrase = $dm031$Fight for your dream rank in timed desk minutes, not in loops of worry about the paper.$dm031$ WHERE phrase = $dm031$Fight for your dream rank in minutes, not in debates with yourself.$dm031$;
UPDATE public.daily_motivational_phrases SET phrase = $dm032$Comparison steals calm under the clock—compare only to yesterday’s attempts.$dm032$ WHERE phrase = $dm032$Comparison steals IQ. Compare only to yesterday’s you.$dm032$;
UPDATE public.daily_motivational_phrases SET phrase = $dm033$Two pages you can recall beat twenty skimmed for comfort on the night before.$dm033$ WHERE phrase = $dm033$Two pages read with attention beat twenty skimmed for comfort.$dm033$;
UPDATE public.daily_motivational_phrases SET phrase = $dm034$Hard work without mock feedback is just fatigue—add a tight learn, test, adjust loop.$dm034$ WHERE phrase = $dm034$Hard work without direction is fatigue; add feedback loops.$dm034$;
UPDATE public.daily_motivational_phrases SET phrase = $dm035$Each corrected mistake is proof you are not stuck—log that proof daily.$dm035$ WHERE phrase = $dm035$Small wins are proof you are not stuck—collect proof daily.$dm035$;
UPDATE public.daily_motivational_phrases SET phrase = $dm036$When the chapter feels endless before the exam, count question batches forward, not imagined mountains.$dm036$ WHERE phrase = $dm036$When the chapter feels endless, count pages forward, not mountains.$dm036$;
UPDATE public.daily_motivational_phrases SET phrase = $dm037$Protect exam deep work like marks depend on it—notifications are not peers during a timed block.$dm037$ WHERE phrase = $dm037$Protect deep work like a pro—notifications are not peers.$dm037$;
UPDATE public.daily_motivational_phrases SET phrase = $dm038$If you envy someone’s exam pace, you do not see their hundreds of timed repetitions.$dm038$ WHERE phrase = $dm038$If you envy someone’s speed, remember you do not see their repetitions.$dm038$;
UPDATE public.daily_motivational_phrases SET phrase = $dm039$Everyone at the desk is tired before the same paper—who returns to attempts after rest wins.$dm039$ WHERE phrase = $dm039$Your competition is also tired—who recovers and returns wins.$dm039$;
UPDATE public.daily_motivational_phrases SET phrase = $dm040$The quiet solver in the corner is not lucky—just logging attempts while others debate the paper.$dm040$ WHERE phrase = $dm040$The quiet student solving in the corner is not lucky—just less loud.$dm040$;
UPDATE public.daily_motivational_phrases SET phrase = $dm041$You do not rise to the exam; you fall to the level of your average Tuesday mock block.$dm041$ WHERE phrase = $dm041$You do not rise to the exam; you fall to your average Tuesday.$dm041$;
UPDATE public.daily_motivational_phrases SET phrase = $dm042$Dreams without a test-aware schedule are hobbies—put today’s attempt block on the calendar.$dm042$ WHERE phrase = $dm042$Dreams without schedules are hobbies. Put today on the calendar.$dm042$;
UPDATE public.daily_motivational_phrases SET phrase = $dm043$Make today’s minimum attempts non-zero—non-zero exam prep days compound.$dm043$ WHERE phrase = $dm043$Make today’s minimum non-zero. Non-zero days compound.$dm043$;
UPDATE public.daily_motivational_phrases SET phrase = $dm044$Win this hour of timed practice before you argue syllabus coverage for the month.$dm044$ WHERE phrase = $dm044$Win the hour before you argue about the month.$dm044$;
UPDATE public.daily_motivational_phrases SET phrase = $dm045$Aspirants overestimate one heroic study day and underestimate ninety ordinary exam reps.$dm045$ WHERE phrase = $dm045$Aspirants overestimate one day and underestimate ninety.$dm045$;
